import { AuthService } from '../services/AuthService';
import { requestBrowserOpen, type BrowserOpenResult } from './browser';
import { errorResult, loginRecovery, type CliCommandResult } from './envelope';
import type { CliIO } from './io';

const SIGN_IN_WAIT_ENV = 'RIVET_SIGN_IN_WAIT_MS';
const DEFAULT_SIGN_IN_WAIT_MS = 45_000;
const SIGN_IN_POLL_INTERVAL_MS = 2_000;

type BrowserSignInOptions = {
  command: string;
  io: CliIO;
  isBrowserDisabled: boolean;
  env: NodeJS.ProcessEnv;
  editor?: string;
  authService?: AuthService;
  launch?: (url: string) => Promise<unknown>;
};

const signInWaitMs = (env: NodeJS.ProcessEnv): number => {
  const parsed = Number.parseInt(env[SIGN_IN_WAIT_ENV] ?? '', 10);
  return Number.isFinite(parsed) && parsed >= 0
    ? parsed
    : DEFAULT_SIGN_IN_WAIT_MS;
};

const signInRequired = ({
  command,
  io,
  authUrl,
  browser,
}: {
  command: string;
  io: CliIO;
  authUrl: string;
  browser?: BrowserOpenResult;
}): CliCommandResult => {
  const message =
    browser?.action === 'launch_requested'
      ? `Rivet sign-in is open in the browser. Finish signing in there, then run \`rivet open\` again. If the browser did not open, use this link: ${authUrl}`
      : `Sign in to Rivet in the browser with this link, then run \`rivet open\` again: ${authUrl}`;
  io.writeProgress(message);
  return errorResult(
    command,
    'AUTH_REQUIRED',
    message,
    browser ? { browser } : undefined,
    loginRecovery(authUrl),
  );
};

export const signInThroughBrowser = async ({
  command,
  io,
  isBrowserDisabled,
  env,
  editor,
  authService = new AuthService(),
  launch,
}: BrowserSignInOptions): Promise<CliCommandResult | null> => {
  const waitAttempts = isBrowserDisabled
    ? 0
    : Math.floor(signInWaitMs(env) / SIGN_IN_POLL_INTERVAL_MS);
  const isSignedIn = async (attempts: number): Promise<boolean> =>
    (await authService.resumePendingLogin(attempts))?.success === true;

  if (await isSignedIn(waitAttempts + 1)) return null;
  const pending = authService.peekPendingLogin();
  if (pending?.authUrl) {
    return signInRequired({ command, io, authUrl: pending.authUrl });
  }

  const begun = await authService.beginGoogleLogin({
    source: 'cli',
    editor,
    noBrowser: true,
  });
  if (!begun.started) {
    return errorResult(
      command,
      'AUTH_REQUIRED',
      `Authentication required. Rivet could not start browser sign-in: ${begun.error} Have the user run \`rivet login\` to sign in.`,
    );
  }
  const browser = await requestBrowserOpen({
    url: begun.authUrl,
    urlField: 'authUrl',
    isBrowserDisabled,
    io,
    launch,
  });
  if (browser.action === 'launch_requested' && (await isSignedIn(waitAttempts)))
    return null;
  return signInRequired({ command, io, authUrl: begun.authUrl, browser });
};
